supplementalBoundDiagnostic.command:
node --input-type=module -e import { deflateRawSync } from "node:zlib";
import { bound, corpus, options } from "./benchmarks/real-world/compression/core.mjs";
let tested=0; const violations=[];
for(const n of [16384,32768,65536,1048576])
for(const seed of [1,2,3,4,5,0x5eed1234])
for(const stride of [0,4,8,16,32,64,128,256,512])
for(const level of [1,6,9]) {
 const x=corpus("poor",n,seed);
 if(stride) for(let i=stride;i<n;i+=stride)
  x.set(x.subarray(Math.max(0,i-4096),Math.max(0,i-4096)+3),i);
 const actual=deflateRawSync(x,options(level)).length;
 tested++;
 if(actual>bound(n)) violations.push({n,seed,stride,level,actual,maximum:bound(n)});
}
console.log(JSON.stringify({tested,violations}));
